  Cu = `Denne udsalgsbegivenhed afventer godkendelse fra Valve`,
  wu = `Brug knappen til højre til at indsende din side til gennemgang mindst 7 dage forud for den ønskede udgivelsesdato, så der er tid nok til gennemgang/godkendelse og eventuelle nødvendige ændringer.`,
  Tu = `Steam-teamet tager kontakt gennem Steamworks-supportsagen, hvis noget skal ændres på siden. Du kan se Steamworks-supportsagen, og tilføje kommentarer efter behov, ved at klikke på knappen til højre.`,
