  Du = `Anmod om gennemgang...`,
  Ou = `Anmod om gennemgang`,
  ku = `Opretter en sag for at anmode om gennemgang med henblik på godkendelse af udsalgsside til udgivelse. Gør dette, når det endelige design af udsalgssiden er færdigt, og alle de spil, du vil fremhæve, er på siden.`,
  Au = `Dette opretter en Steamworks-supportsag med en anmodning til Valve om at gennemgå udsalgssiden. Dette skal først gøres, når billederne og teksten er færdig, og spillisten er klar.`,
  ju = `Sørg for, at begivenhedens titel og formål er tydeligt angivet øverst på siden. Til fremvisninger kan du få brug for at have en tekstsektion øverst på siden for at beskrive, hvad fremvisningen handler om, og hvordan den fungerer.`,
  Mu = `Udsalgssiden vil være låst, når den er blevet gennemgået. Hvis du har brug for at ændre noget efter gennemgangen, eller når begivenheden begynder, kan du skrive en kommentar om, hvad ændringerne omfatter, og hvorfor de ikke kunne foretages inden gennemgangen.`,
