  oV = `Sid ned og slap af`,
  sV = `Undlad at foreslå en bestemt kategori, og lad i stedet dine fans vælge den kategori, som de synes passer bedst til dit spil. Begivenheden vil stadig have et link til nomineringssiden.`,
  cV = `Ingen kategori`,
  lV = `Måske var det spillets fordybende gameplay eller dets gribende historie... dets kreative figurer, fejlfrie design eller vanedannende multiplayer. Uanset årsagen er vinderen af prisen som årets bedste spil 2020 en øjeblikkelig klassiker.`,
  uV = `Årets VR-spil efterligner ikke bare virkeligheden. Dette spil forbedrer virkeligheden, udnytter VR-mediet og flytter grænserne for den virtuelle verden.`,
  dV = `Dette spil har været på markedet i et stykke tid. Holdet har for længst afsløret deres lille kreative baby, men som de gode forældre de er, vil udviklerne fortsætte med at pleje og støtte deres barn. Selv efter alle disse år bliver der stadig lavet nyt indhold til spillet.`,
  fV = `Der findes nogle spil, der bare ikke er de samme, når man spiller dem alene. Måske mangler du en ven til at beskytte din bagside. Måske mangler du en ven, du kan stikke i ryggen. Uanset hvad, så er der morskab i vente, hvis du samler vennerne og spiller dette spil.`,
  pV = `Visuel stil handler ikke om at opnå en nøjagtig grafisk gengivelse (som ellers er et ædelt mål i sig selv)… det beskriver et særligt udseende, som gennemtrænger hele spillet.`,
  mV = `Dette spils designere er på frontlinjen med kreative eksperimenter, der giver et nyt perspektiv og forbløffende overraskelser. Spillet begejstrede, inspirerede og underholdt med en originalitet, vi ikke har set i spil før.`,
  hV = `Dette spil belønner udholdenhed og er ikke for sarte sjæle. Det er det sværeste spil, vi nogensinde har elsket.`,
  gV = `Denne ukendte helt fortjener at blive hyldet for sin fantastiske musik. Det er det bedste af det bedste! `,
  _V = `Nogle gange har man bare brug for et spil med en stærk fortælling, og dette spil har slagkraft! Det er lige så gribende som en sæbeopera og lige så godt skruet sammen som et førsteklasses manuskript. Bravissimo – det får os til at føle noget!`,
  vV = `Dette spil er modgiften til en travl dag. Det er roligt og afslappende og får dine bekymringer til at smelte væk. Spillet giver dig et øjeblik af zen.`,
  yV = `Vil du ændre din nominering?`,
  bV = `Du kan kun nominere et spil i hver kategori, og du har allerede nomineret %1$s i denne kategori. Vil du gerne nominere %2$s i stedet?`,
