  fH = `Denne ukendte helt fortjener at blive hyldet for sin fantastiske musik. Det er det bedste af det bedste! `,
  pH = `Nogle gange har man bare brug for et spil med en stærk fortælling, og dette spil har slagkraft! Det er lige så gribende som en sæbeopera og lige så godt skruet sammen som et førsteklasses manuskript. Bravissimo – det får os til at føle noget!`,
  mH = `Dette spil er modgiften til en travl dag. Det er roligt og afslappende og får dine bekymringer til at smelte væk. Spillet giver dig et øjeblik af zen.`,
  hH = `Dette spil var så godt, at du havde lyst til at tage det med dig overalt. Og det gjorde du! Heldigvis blev alt, som gjorde det godt at spille det på din computer derhjemme, endnu bedre på farten.`,
