  HH = `%1$s poletter`,
  UH = `Kunne ikke åbne kuvert`,
  WH = `KEJSERENS STORE KAPLØB`,
  GH = `Sagnet om den kinesiske dyrekreds`,
  KH = `Del I af IV`,
  qH = `Del II af IV`,
  JH = `Del III af IV`,
  YH = `Del IV af IV`,
  XH = `Jadekejseren kaldte alle dyrene i sit rige sammen til et kapløb til Det Himmelske Palads og erklærede, at de første tolv, der kom i mål, ville blive hædret med en plads i hans nye kalender.

Snedige Rotte var den første, der krydsede floden til Himlen. Rotte var ikke vild med at svømme, så den fik et lift på ryggen af den tillidsfulde Okse og sprang glad over i Kejserens have, lige inden de to nåede bredden.

Rolige Okse krydsede floden i ro og mag. Den var ligeglad med resultatet af kapløbet og var godt tilfreds med sin rolle i Rottes succes.`,
  ZH = `Uafhængige Tiger var for forsigtig til at overhale Okse, men tænkte, at en tredjeplads var bedre end ingen plads.

Hurtige Hare hoppede op på en træstamme, som knap nok flyttede sig. Men held tjente Hare bedre end strategi, og en gunstig vind førte den improviserede båd sikkert afsted.

Flyvende Drages fordelagtige position afslørede, at en landsby var i nød, så selvfølgelig stoppede Drage for at hjælpe og gav endda Hare et skub i den rigtige retning på floden. Ære var langt vigtigere end at vinde, og Drage var glad for sin femteplads.`,
  QH = `Listige Slange var ikke interesseret i et langdistanceløb, så den snoede sig ubemærket rundt om Hests forben.

Da Hest nærmede sig målstregen i fuld galop, rullede Slange sig ud og skræmte gangeren lige akkurat længe nok til at glide ind på sjettepladsen med den nervøse Hest lige bagefter.`,
  $H = `Ged, Abe og Hane arbejdede sammen, men lod Ged tage ottendepladsen, da den var holdets rygrad. Muntre Abe var den næste, og Hane spankulerede over målstregen på en tiendeplads, stolt over den retfærdige rækkefølge.

Legesyge Hund var mest interesseret i at pjaske rundt og syntes, at en ellevteplads var et godt bytte for al morskaben.

Til sidst kom Gris, som havde stoppet for at få sig en snack og en lur. Den vidste, at alle dyrene nok skulle få en plads i solen hos Kejseren.`,
